<?php $pageTitle='Create your account'; require 'db/connection.php'; require 'includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pass=$_POST['password']??''; $digits=preg_replace('/\D/','',$phone); if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6){$error='Enter a valid name, email and password of at least 6 characters.';}elseif(strlen($digits)<10||strlen($digits)>15){$error='Please enter a valid real phone number (10 to 15 digits).';}else{try{$st=$pdo->prepare('INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)');$st->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);flash('main','Account created. Please log in.');redirect('login.php');}catch(PDOException $e){$error='That email is already registered.';}}} include 'includes/header.php'; ?><div class="form-page"><div class="panel"><span class="eyebrow">Welcome</span><h1>Create an account</h1><?php if(!empty($error)): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input type="tel" name="phone" required placeholder="e.g. 9876543210" pattern="^(\+?[0-9\s-]{10,15})$" maxlength="15" title="Please enter a valid real phone number (10 to 15 digits)"></div><div class="field"><label>Password</label><input type="password" name="password" minlength="6" required></div><button class="button" type="submit">Register</button></form><p class="muted">Already registered? <a href="login.php">Log in</a></p></div></div><?php include 'includes/footer.php'; ?>
